-- Notifications V1: schema (generated by drizzle-kit from the notifications
-- module's schema.ts).
--
--   notifications             one person's inbox: typed, localized by key,
--                             unread while read_at is null; one row per source
--                             fact and recipient (notifications_dedupe_unique)
--   notification_preferences  per person and category: in-app, realtime, push;
--                             no row means the defaults
--   notification_devices      app installations that receive push; one owner
--                             per (provider, token)
--
-- Account ids are deliberately not foreign keys across modules: suspending or
-- disabling an account leaves its notification history alone.
-- See docs/architecture/notifications.md.

CREATE TABLE "notification_devices" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"platform" text NOT NULL,
	"provider" text NOT NULL,
	"token" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"last_seen_at" timestamp with time zone NOT NULL,
	"disabled_at" timestamp with time zone,
	CONSTRAINT "notification_devices_token_unique" UNIQUE("provider","token"),
	CONSTRAINT "notification_devices_platform_valid" CHECK ("notification_devices"."platform" in ('IOS', 'ANDROID', 'WEB')),
	CONSTRAINT "notification_devices_provider_valid" CHECK ("notification_devices"."provider" in ('APNS', 'FCM')),
	CONSTRAINT "notification_devices_apns_is_ios" CHECK ("notification_devices"."provider" <> 'APNS' or "notification_devices"."platform" = 'IOS'),
	CONSTRAINT "notification_devices_token_length" CHECK (char_length("notification_devices"."token") between 32 and 1024)
);
