CREATE TABLE "notification_preferences" (
	"user_id" text NOT NULL,
	"category" text NOT NULL,
	"in_app" boolean NOT NULL,
	"realtime" boolean NOT NULL,
	"push" boolean NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "notification_preferences_user_id_category_pk" PRIMARY KEY("user_id","category"),
	CONSTRAINT "notification_preferences_category_shape" CHECK ("notification_preferences"."category" ~ '^[A-Z][A-Z_]{0,31}$')
);
--> statement-breakpoint
CREATE TABLE "notifications" (
	"id" text PRIMARY KEY NOT NULL,
	"recipient_user_id" text NOT NULL,
	"type" text NOT NULL,
	"category" text NOT NULL,
	"title_key" text NOT NULL,
	"body_key" text NOT NULL,
	"params" jsonb NOT NULL,
	"target" jsonb NOT NULL,
	"dedupe_key" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"read_at" timestamp with time zone,
	CONSTRAINT "notifications_dedupe_unique" UNIQUE("recipient_user_id","dedupe_key"),
	CONSTRAINT "notifications_type_shape" CHECK ("notifications"."type" ~ '^[A-Z][A-Z_]{0,63}$'),
	CONSTRAINT "notifications_category_shape" CHECK ("notifications"."category" ~ '^[A-Z][A-Z_]{0,31}$'),
	CONSTRAINT "notifications_template_keys_shape" CHECK ("notifications"."title_key" ~ '^notification\.[a-z0-9_]{1,40}\.[a-z0-9_]{1,40}$' and "notifications"."body_key" ~ '^notification\.[a-z0-9_]{1,40}\.[a-z0-9_]{1,40}$'),
	CONSTRAINT "notifications_params_is_object" CHECK (jsonb_typeof("notifications"."params") = 'object'),
	CONSTRAINT "notifications_target_has_kind" CHECK (jsonb_typeof("notifications"."target") = 'object' and jsonb_typeof("notifications"."target" -> 'kind') = 'string'),
	CONSTRAINT "notifications_dedupe_key_length" CHECK (char_length("notifications"."dedupe_key") between 1 and 200),
	CONSTRAINT "notifications_read_after_created" CHECK ("notifications"."read_at" is null or "notifications"."read_at" >= "notifications"."created_at")
);
