CREATE INDEX "notification_devices_user_enabled_idx" ON "notification_devices" USING btree ("user_id","last_seen_at") WHERE "notification_devices"."disabled_at" is null;--> statement-breakpoint
CREATE INDEX "notifications_recipient_created_idx" ON "notifications" USING btree ("recipient_user_id","created_at","id");--> statement-breakpoint
CREATE INDEX "notifications_recipient_unread_idx" ON "notifications" USING btree ("recipient_user_id","created_at","id") WHERE "notifications"."read_at" is null;